}' > "$NEXUS_OUTPUT_DIR/shards"

tr -d '{}" \n' < "$NEXUS_INPUT_DIR/shard" | tr ',' '\n' | awk -F: '
function feat(i, j) { return ((i * (7919 + 104729 * j) + 13 * j) % 1000) / 250.0 - 2 }
function positive(i,   z) {
  z = 1.2 * feat(i, 1) - 0.8 * feat(i, 2) + 0.5 * feat(i, 3) - 0.1
  return (1 / (1 + exp(-z))) >= 0.5
}
{ f[$1] = $2 }
END {
  for (i = f["start"]; i < f["stop"]; i++) { rows++; ids += i; pos += positive(i) }
  printf "{\"shard\":%d,\"rows\":%d,\"positives\":%d,\"id_sum\":%.0f}", f["shard"], rows, pos, ids
}' > "$NEXUS_OUTPUT_DIR/summary" && cat "$NEXUS_OUTPUT_DIR/summary"

v() { tr -d '"\n ' < "$NEXUS_INPUT_DIR/$1"; }; tr -d '[]{}" \n' < "$NEXUS_INPUT_DIR/summaries" | tr ',' '\n' | awk -F: -v n="$(v records)" -v size="$(v shard_size)" '
function feat(i, j) { return ((i * (7919 + 104729 * j) + 13 * j) % 1000) / 250.0 - 2 }
function positive(i,   z) {
