  return (1 / (1 + exp(-z))) >= 0.5
}
$0 == "null" { missing++; next }
$1 == "shard" { shards++; shard_sum += $2 }
$1 == "rows" { rows += $2 }
$1 == "positives" { pos += $2 }
$1 == "id_sum" { ids += $2 }
END {
