  printf "{\"records\":%d,\"shards\":%d,\"missing_shards\":%d,\"rows\":%d,\"positives\":%d,\"positives_unsharded\":%d,\"positive_rate\":%.4f,\"ok\":%s}\n", n, shards, missing, rows, pos, want_pos, (n ? want_pos / n : 0), ok ? "true" : "false"
  if (!ok) {
    printf "batch inference check failed: %d/%d shards reported (%d missing), %d/%d rows, " , shards, want_shards, missing, rows, n > "/dev/stderr"
    printf "id sum %.0f vs %.0f, positives %d vs %d unsharded\n", ids, want_ids, pos, want_pos > "/dev/stderr"
    exit 1
  }
}' > "$NEXUS_OUTPUT_DIR/result" && cat "$NEXUS_OUTPUT_DIR/result"

