function sigm(z) { if (z > 30) return 1; if (z < -30) return 0; return 1 / (1 + exp(-z)) }
function tanh_(z,   e) { if (z > 15) return 1; if (z < -15) return -1; e = exp(2 * z); return (e - 1) / (e + 1) }
function init(m, h, k,   i, j) {
  MODEL = m; H = h; K = k; B2 = 0
