  split("electronics grocery apparel home toys sports books beauty", cat, " ");
  n = region; gsub(/[^0-9]/, "", n); s = seed * 100003 + n * 7919;
  srand(s);
  print "order_id,region,category,product,qty,unit_price,order_date";
  for (i = 1; i <= rows; i++) {
    c = cat[int(rand() * 8) + 1];
    p = c "-sku-" int(rand() * 25);
    q = int(rand() * 9) + 1;
    pr = sprintf("%.2f", 2 + rand() * 198);
    d = sprintf("2026-%02d-%02d", int(rand() * 12) + 1, int(rand() * 28) + 1);
    r = rand();
    if (r < 0.0025) q = "";
    else if (r < 0.005) pr = "-" pr;
    printf "%s-%07d,%s,%s,%s,%s,%s,%s\n", region, i, region, c, p, q, pr, d;
  }
}' > "$NEXUS_OUTPUT_DIR/csv"

