cd "$NEXUS_INPUT_DIR" && awk -F'[{}":,]+' '
FILENAME ~ /^quality_/ { for (i = 2; i < NF; i += 2) q[$i] += $(i + 1); next }
$2 == "category" { rev[$3] += $5; units[$3] += $7; orders[$3] += $9; agg += $9 }
END {
  if (q["clean"] != agg || q["clean"] + q["rejected"] != q["rows"]) {
    printf "ROW ACCOUNTING FAILED: rows=%d clean=%d rejected=%d aggregated=%d\n", q["rows"], q["clean"], q["rejected"], agg > "/dev/stderr";
    exit 1;
  }
  for (c in rev) { total += rev[c]; if (rev[c] > best) { best = rev[c]; top = c } }
  printf "{\"regions\":%d,\"rows\":%d,\"clean\":%d,\"rejected\":%d,\"reject_rate_pct\":%.3f,\"categories\":{", 16, q["rows"], q["clean"], q["rejected"], 100 * q["rejected"] / q["rows"];
  sep = "";
  for (c in rev) { printf "%s\"%s\":{\"revenue\":%.2f,\"units\":%d,\"orders\":%d}", sep, c, rev[c], units[c], orders[c]; sep = "," }
  printf "},\"total_revenue\":%.2f,\"top_category\":\"%s\",\"row_accounting\":\"ok\"}\n", total, top;
}' quality_* summary_* > "$NEXUS_OUTPUT_DIR/report" && cat "$NEXUS_OUTPUT_DIR/report"

awk -F, -v out="$NEXUS_OUTPUT_DIR/clean" '
NR == 1 { print > out; next }
{ total++ }
NF != 7              { bad++; reason["columns"]++;   next }
$5 !~ /^[0-9]+$/     { bad++; reason["qty"]++;       next }
$6 !~ /^[0-9.]+$/    { bad++; reason["price"]++;     next }
{ print > out; good++ }
END {
  printf "{\"rows\":%d,\"clean\":%d,\"rejected\":%d,\"bad_qty\":%d,\"bad_price\":%d,\"bad_columns\":%d}",
    total, good, bad, reason["qty"], reason["price"], reason["columns"];
}' "$NEXUS_INPUT_DIR/csv" > "$NEXUS_OUTPUT_DIR/quality"

