  if (match(s, "\"" k "\":[^,}]*")) { m = substr(s, RSTART, RLENGTH); sub(/^"[^"]+":/, "", m); return m }
  return "" }
{
  j++; node[j] = get($0, "node"); kind[j] = get($0, "kind"); req[j] = get($0, "requested") + 0;
  got[j] = get($0, "assigned") + 0; s[j] = get($0, "start") + 0; e[j] = get($0, "end") + 0;
  mode = get($0, "gpu"); dev[j] = get($0, "devices");
  host[j] = get($0, "worker"); wkind = get($0, "worker_kind"); wgpus = get($0, "worker_gpus") + 0;
  label[host[j]] = get($0, "host");
  if (host[j] == "") { bad++; why = why sprintf("%s: its agent did not report NEXUS_WORKER_ID (too old for this audit); ", node[j]) }
  if (host[j] in wk && (wk[host[j]] != wkind || wcap[host[j]] != wgpus)) { bad++; why = why sprintf("worker %s reported different GPUs to different jobs; ", host[j]) }
  wk[host[j]] = wkind; wcap[host[j]] = wgpus;
  if (wkind != kind[j]) { bad++; why = why sprintf("%s asked for %s but ran on worker %s (%s), which advertises %s; ", node[j], kind[j], host[j], label[host[j]], (wkind == "" ? "no GPUs" : wkind)) }
  if (got[j] != req[j]) { bad++; why = why sprintf("%s asked for %s GPUs, was given %s; ", node[j], req[j], got[j]) }
}
END {
  for (a = 1; a <= j; a++) {
    used = 0; for (b = 1; b <= j; b++) if (host[b] == host[a] && s[b] <= s[a] && e[b] > s[a]) used += req[b];
    if (used > peak[host[a]]) peak[host[a]] = used;
  }
  for (a = 1; a <= j; a++) for (b = a + 1; b <= j; b++)
    if (host[a] == host[b] && s[a] < e[b] && s[b] < e[a]) {
      na = split(dev[a], da, ","); nb = split(dev[b], db, ",");
      for (x = 1; x <= na; x++) for (y = 1; y <= nb; y++) if (da[x] == db[y]) {
        bad++; why = why sprintf("%s and %s ran at the same time on %s and both used device %s; ", node[a], node[b], host[a], da[x]) }
    }
  for (h in peak) {
