    peaks = peaks sprintf("%s\"%s\":{\"host\":\"%s\",\"gpu_kind\":\"%s\",\"peak_gpus\":%d,\"capacity\":%d}", (peaks == "" ? "" : ","), h, label[h], wk[h], peak[h], wcap[h]);
  }
  first = s[1]; last = e[1]; for (a = 2; a <= j; a++) { if (s[a] < first) first = s[a]; if (e[a] > last) last = e[a] }
  printf "{\"jobs\":%d,\"violations\":%d,\"gpu\":\"%s\",\"makespan_seconds\":%d,\"hosts\":{%s}", j, bad, mode, last - first, peaks;
  if (bad) { printf ",\"problems\":\"%s\"}\n", why; print "GPU AUDIT FAILED: " why > "/dev/stderr"; exit 1 }
  printf "}\n";
}' > "$NEXUS_OUTPUT_DIR/audit" && cat "$NEXUS_OUTPUT_DIR/audit"

cd "$NEXUS_INPUT_DIR" && cat * | sed 's/}{/}\n{/g' | awk -v cap=42949672960 -v migcap="1g.10gb:3 3g.40gb:1" '
function get(s, k,   m) {
