BEGIN { n = split(migcap, c, " "); for (i = 1; i <= n; i++) { split(c[i], p, ":"); mcap[p[1]] = p[2] } }
{ j++; node[j] = get($0, "node"); mode[j] = get($0, "mode"); mem[j] = get($0, "mem") + 0;
