    for (i = 1; i <= n; i++) {
      r = w1 * X1[i] + w2 * X2[i] + w3 * X3[i] + b - Y[i];
      g1 += r * X1[i]; g2 += r * X2[i]; g3 += r * X3[i]; gb += r;
    }
    w1 -= lr * (2 * g1 / n + 2 * l2 * w1); w2 -= lr * (2 * g2 / n + 2 * l2 * w2);
    w3 -= lr * (2 * g3 / n + 2 * l2 * w3); b -= lr * 2 * gb / n;
  }
  for (i = 1; i <= t; i++) { m += TY[i] }
  m /= t;
  for (i = 1; i <= t; i++) {
    p = w1 * T1[i] + w2 * T2[i] + w3 * T3[i] + b;
    sse += (TY[i] - p) ^ 2; sst += (TY[i] - m) ^ 2;
  }
  printf "{\"lr\":%s,\"epochs\":%d,\"l2\":%s,\"mse\":%.6f,\"r2\":%.6f,\"w1\":%.4f,\"w2\":%.4f,\"w3\":%.4f,\"b\":%.4f,\"train_rows\":%d,\"test_rows\":%d}", lr, epochs, l2, sse / t, 1 - sse / sst, w1, w2, w3, b, n, t;
}' "$NEXUS_INPUT_DIR/train" "$NEXUS_INPUT_DIR/test" > "$NEXUS_OUTPUT_DIR/metrics"
